import {accountFilterOptions,selectedAccounts} from './catalog.c5d5e89d01b0.mjs';
const ROUTE_LABELS=new Map([['#/materials','素材库'],['#/today','新内容雷达'],['#/brief','每日选材晨报'],['#/accounts','对标账号'],['#/observations','观察记录'],['#/submit','提交账号']]);
const CONTENT_LABELS={product_showcase:'产品纯展示',product_selling:'产品带货',product_talking:'产品口播',creator_selling:'达人带货',ugc_review:'UGC 使用体验',comparison:'测评/对比',tutorial:'教程演示',story:'剧情植入',unboxing:'开箱素材',live_clip:'直播切片',brand_ad:'品牌广告',unknown:'暂不确定'};
const REVIEW_LABELS={pending:'待审核',approved:'已确认',rejected:'已淘汰',needs_review:'需复核'};
