const POOL_LABELS={company:'公司对标',market:'市场对标',all:'全部范围'};
const MONITORING_LABELS={identity_blocked:'身份待确认',blocked:'监控受阻',running:'正在检查',queued:'等待检查',active:'日计划已启用',not_monitored:'未加入日计划',unknown:'监控状态未知'};
const LEGACY_ACCOUNT_LABELS={ready:'历史扫描完成',pending:'历史等待扫描',running:'历史扫描中',failed:'历史扫描失败',blocked:'历史扫描受阻',disabled:'历史未启用'};
export function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function videoVariant(item){if(['clip','full','hd'].includes(item.kind))return item.kind;if(item.quality==='preview-hd1080-v2')return 'hd';if(item.quality==='observation-clip-8s')return 'clip';return 'video';}
export function qualityLabel(item){const size=item.width&&item.height?`${item.width}×${item.height}`:'尺寸未知';if(item.kind==='cover')return `封面 · ${size}`;if(item.kind==='image')return `图集图片 · ${size}`;const variant=videoVariant(item);if(variant==='clip')return `${item.duration_seconds?`${item.duration_seconds} 秒`:'时长未知'}短片 · ${size}`;const kind=variant==='hd'?'高清文件':variant==='full'?'完整文件':'轻量视频';return `${kind} · ${size}${item.duration_seconds?` · ${item.duration_seconds} 秒`:''}`;}
function mediaFrom(manifest,id){return manifest.media instanceof Map?manifest.media.get(id):manifest.media?.[id];}
function metric(value){return value===null||value===undefined?'未知':Number(value).toLocaleString('zh-CN');}
function nav(route){return [...ROUTE_LABELS].map(([href,label])=>`<a href="${href}"${href===route?' aria-current="page"':''}>${label}</a>`).join('');}
function badges(values=[],extra=''){return values.map(value=>`<span class="badge ${extra}">${escapeHtml(value)}</span>`).join('');}
function fieldValue(filters,name){return escapeHtml(filters?.[name]??'');}
function option(value,label,current){return `<option value="${escapeHtml(value)}"${current===value?' selected':''}>${escapeHtml(label)}</option>`;}
const fieldOptionsCache=new WeakMap();
const poolCountsCache=new WeakMap();
function selectField(label,name,records,key,current,{labels,arrays=false,all='全部'}={}){
  let cached=fieldOptionsCache.get(records);if(!cached){cached=new Map();fieldOptionsCache.set(records,cached);}
  const cacheKey=`${key}:${arrays}`;
  let items=cached.get(cacheKey);
  if(!items){const values=new Set();for(const record of records){const raw=record[key];if(arrays){for(const value of raw||[])if(value)values.add(value);}else if(raw)values.add(raw);}items=[...values].sort((a,b)=>String(a).localeCompare(String(b),'zh-CN'));cached.set(cacheKey,items);}
  const noClassification=name==='content_type'&&!items.length;
  return `<label>${label}<select name="${name}"${noClassification?' disabled':''}>${option('',all,current||'')}${items.map(value=>option(value,labels?.[value]||value,current||'')).join('')}</select>${noClassification?'<small class="muted">暂无内容分类</small>':''}</label>`;
}
function poolCounts(records){let result=poolCountsCache.get(records);if(!result){result={company:0,market:0,all:0};for(const item of records){if(item.pool==='company')result.company++;if(item.pool==='market')result.market++;if(item.pool!=='all')result.all++;}poolCountsCache.set(records,result);}return result;}
function textField(label,name,filters,type='text'){return `<label>${label}<input name="${name}" type="${type}" value="${fieldValue(filters,name)}"${type==='search'?' maxlength="100"':''}${type==='number'?' min="0"':''}${type==='date'&&filters.date_status==='unknown'?' disabled':''}></label>`;}
function accountPicker(records,filters){
  const chosen=new Set(selectedAccounts(filters)),pool=filters.pool||'company',options=[...accountFilterOptions(records)];
  for(const account of chosen)if(!options.some(option=>option.account===account))options.push({account,display:account,pools:[]});
  const choices=options.map(option=>{
    const inScope=option.pools.includes('all')||option.pools.some(value=>pool==='all'||value===pool);
    const poolLabel=option.pools.map(value=>POOL_LABELS[value]).filter(Boolean).join(' / ')||'本页无账号记录';
    return `<label class="account-option" data-account-option data-account-in-scope="${inScope}" data-account-search="${escapeHtml(`${option.display} @${option.account}`.toLocaleLowerCase())}"${inScope?'':' hidden'}><input type="checkbox" name="accounts" value="${escapeHtml(option.account)}"${chosen.has(option.account)?' checked':''}><span><strong>${escapeHtml(option.display)}</strong><span class="muted">@${escapeHtml(option.account)} · ${escapeHtml(poolLabel)}</span></span></label>`;
  }).join('');
  return `<details class="account-picker" data-account-picker><summary>达人账号 <span data-account-count>已选 ${chosen.size} 个账号</span></summary><div class="account-picker-body"><p class="muted">当前范围：${POOL_LABELS[pool]||POOL_LABELS.company}。选择任一账号均可命中，并与其他筛选条件同时生效。</p><label>搜索昵称或 @账号<input type="search" data-account-search maxlength="160" placeholder="输入昵称或账号，不影响文案搜索"></label><div class="account-picker-actions"><button type="button" data-account-select-matches>选择搜索结果</button><button type="button" data-account-clear>清空已选</button><button type="submit" class="primary">应用账号筛选</button></div><p class="account-picker-status muted" data-account-status role="status" aria-live="polite"></p><div class="account-options" role="group" aria-label="可选达人账号">${choices}</div><p class="muted" data-account-empty hidden>当前范围内没有匹配账号，请调整搜索词或切换公司 / 市场范围。</p></div></details>`;
}
function sortFields(filters,route){const routeSorts=route==='#/accounts'?[['followers','粉丝数'],['material_count','素材数'],['observation_count','观察数'],['account','账号名']]:route==='#/observations'?[['views','播放量'],['checked','最近检查'],['published','发布日期'],['account','账号名']]:route==='#/brief'?[['view_delta','播放增量'],['views','播放量（最近记录）'],['published','发布日期']]:[['views','播放量'],['likes','点赞'],['comments','评论'],['shares','分享'],['published','发布日期'],['viral_score','爆款分']];return `<label>排序<select name="sort">${routeSorts.map(([value,label])=>option(value,label,filters.sort||'views')).join('')}</select></label><label>方向<select name="direction">${option('desc','从高到低',filters.direction||'desc')}${option('asc','从低到高',filters.direction||'desc')}</select></label>`;}
function filterForm(route,records,filters){let fields=accountPicker(records,filters)+textField('搜索账号或文案','query',filters,'search');fields+=selectField('国家/地区','country',records,'country',filters.country);fields+=selectField('类目','category',records,'categories',filters.category,{arrays:true});fields+=selectField('产品','product',records,'products',filters.product,{arrays:true});
  if(route==='#/materials')fields+=`${selectField('审核状态','review_status',records,'review_status',filters.review_status,{labels:REVIEW_LABELS})}${selectField('内容类型','content_type',records,'content_type',filters.content_type,{labels:CONTENT_LABELS})}${selectField('画面','media',[{media:'available'},{media:'missing'}],'media',filters.media,{labels:{available:'已有画面',missing:'待恢复'}})}${textField('开始日期','date_from',filters,'date')}${textField('结束日期','date_to',filters,'date')}`;
  if(route==='#/brief')fields+=`${selectField('晨报日期','report_day',records,'report_day',filters.report_day)}${selectField('增长信号','signal',records,'signal_quality',filters.signal,{labels:SIGNAL_LABELS})}${selectField('内容类型','content_type',records,'content_type',filters.content_type,{labels:CONTENT_LABELS})}${selectField('画面','media',[{media:'available'},{media:'missing'}],'media',filters.media,{labels:{available:'已有画面',missing:'待恢复'}})}`;
  if(route==='#/accounts')fields+=selectField('归类范围','classification_scope',records,'classification_scope',filters.classification_scope,{labels:SCOPE_LABELS});
  if(route==='#/today'||route==='#/observations')fields+=`${selectField('记录状态','state',records,'state',filters.state,{labels:STATE_LABELS})}${textField('最低播放量','min_views',filters,'number')}${selectField('画面','media',[{media:'available'},{media:'missing'}],'media',filters.media,{labels:{available:'已有画面',missing:'待恢复'}})}${textField('开始日期','date_from',filters,'date')}${textField('结束日期','date_to',filters,'date')}`;
  if(['#/materials','#/today','#/observations'].includes(route))fields+=`${selectField('发布日期状态','date_status',[{state:'known'},{state:'unknown'}],'state',filters.date_status,{labels:{known:'日期已知',unknown:'日期未知'}})}<p class="filter-help muted">日期范围按作品发布日期筛选；选择“日期未知”会清空并停用日期范围。</p>`;
  fields+=sortFields(filters,route);return `<form id="filters" class="filters">${fields}<button type="submit" class="primary">筛选</button><button type="button" data-reset-filters>重置筛选</button><p class="filter-error" data-filter-error role="alert" hidden></p></form>`;
}
function paginationControls(pagination){if(!pagination||pagination.totalPages<=1)return '';return `<nav class="pagination" aria-label="分页"><button type="button" data-page="${pagination.page-1}"${pagination.page<=1?' disabled':''}>上一页</button><span>第 ${pagination.page}/${pagination.totalPages} 页</span><button type="button" data-page="${pagination.page+1}"${pagination.page>=pagination.totalPages?' disabled':''}>下一页</button></nav>`;}
function summaryCard(record){const m=record.metrics;return `<article class="summary-card"><p class="eyebrow">${escapeHtml(record.report_day)} · ${record.status==='complete'?'完整':'部分完成'}</p><h2>晨报数据概况</h2><p class="muted">本期发布时的采样结果；不代表当前恢复状态，且不随下方筛选变化。</p><div class="summary-metrics"><span>账号成功 <strong>${metric(m.accounts_success)}</strong></span><span>账号受阻 <strong>${metric(m.accounts_blocked)}</strong></span><span>增长信号 <strong>${metric(m.posts_sampled)}</strong></span><span>延后处理 <strong>${metric(m.posts_deferred)}</strong></span></div><p class="muted">发布时间 ${escapeHtml(record.published_at||'未知')}</p></article>`;}
function recordMedia(record,manifest){
  const media=(record.media_ids||[]).map(id=>{const item=mediaFrom(manifest,id);return item?{...item,id}:null;}).filter(Boolean);
  const images=media.filter(item=>item.kind==='image'&&item.content_type?.startsWith('image/')&&item.url);
  const cover=media.find(item=>item.kind==='cover'&&item.url)||images[0];
  const ranks={video:0,clip:1,full:2,hd:3};
  const videos=media.filter(item=>['clip','video','full','hd'].includes(item.kind)&&item.content_type?.startsWith('video/')&&item.url).sort((a,b)=>ranks[videoVariant(a)]-ranks[videoVariant(b)]);
  return {cover,video:videos[0],videos,images};
}
function galleryButton(images,frame=false,poster=''){
  const label=`查看图集 · ${images.length} 张`,ids=images.map(item=>item.id).join(',');
  return `<button type="button" class="${frame?'media-frame media-trigger':'media-button'}" data-gallery-ids="${escapeHtml(ids)}" aria-label="${label}">${frame?`<img src="${escapeHtml(poster||images[0].url)}" alt="图集封面" loading="lazy"><span class="play-badge">${label}</span>`:label}</button>`;
}
function mediaBlock(record,manifest){
  const {cover,video,images}=recordMedia(record,manifest);
  if(images.length)return galleryButton(images,true,cover?.url);
  if(!video)return `<div class="media-frame">${cover?.url?`<img src="${escapeHtml(cover.url)}" alt="作品封面" loading="lazy">`:'<span>本机没有可发布的封面</span>'}<span class="media-unavailable">${record.content_kind==='carousel'?'本机图集待恢复':'本机视频待恢复'}</span></div>`;
  const label=qualityLabel(video),poster=cover?.url||'';
  return `<button type="button" class="media-frame media-trigger" data-media-url="${escapeHtml(video.url)}" data-media-poster="${escapeHtml(poster)}" data-media-label="${escapeHtml(label)}" aria-label="播放视频 ${escapeHtml(record.post_id||'')}">${poster?`<img src="${escapeHtml(poster)}" alt="作品封面" loading="lazy">`:'<span>点击加载视频</span>'}<span class="play-badge">▶ 播放视频</span></button>`;
}
function sourceActions(record,{videos=[],images=[],cover=null,profile=false}={}){
  const source=(profile?record.profile_url||record.source_url:record.source_url||record.profile_url)||'';
  const videoButtons=videos.map(item=>`<button type="button" class="media-button" data-media-url="${escapeHtml(item.url)}" data-media-poster="${escapeHtml(cover?.url||'')}" data-media-label="${escapeHtml(qualityLabel(item))}">${videos.length>1?`播放${escapeHtml(qualityLabel(item))}`:'播放视频'}</button>`).join('');
  return `<div class="card-actions">${images.length?galleryButton(images):videoButtons}${source?`<a href="${escapeHtml(source)}" target="_blank" rel="noopener noreferrer">${profile?'查看账号主页':'查看原作品'}</a><button type="button" data-copy-url="${escapeHtml(source)}">复制链接</button>`:''}</div>`;
}
function accountCard(record){
  const title=record.display_name||record.account_display||record.username||'未命名账号';
  const status=record.monitoring_status?`当前监控：${MONITORING_LABELS[record.monitoring_status]||MONITORING_LABELS.unknown} · 最近检查 ${record.last_checked_at?.slice(0,16)||'未知'}`:`历史扫描状态：${LEGACY_ACCOUNT_LABELS[record.account_status]||'未知'} · 历史扫描 ${record.last_scanned_at?.slice(0,16)||'未知'}`;
  return `<article class="card account-card"><div class="card-body"><p class="eyebrow">${escapeHtml(SCOPE_LABELS[record.classification_scope]||record.classification_scope||'暂未归类')}</p><h2>${escapeHtml(title)}</h2><p class="account">@${escapeHtml(record.username||'')} · ${escapeHtml(record.country||'地区未知')}</p><div>${badges(record.categories)}${badges(record.products)}</div><div class="stats"><span>粉丝 <strong>${metric(record.metrics?.followers)}</strong></span><span>素材 <strong>${metric(record.metrics?.material_count)}</strong></span><span>观察 <strong>${metric(record.metrics?.observation_count)}</strong></span></div><p class="muted">${escapeHtml(status)}</p>${sourceActions(record,{profile:true})}</div></article>`;
}
function contentCard(record,manifest){
  const {cover,video,videos,images}=recordMedia(record,manifest),title=record.description||record.account_display||record.account||'未命名记录';
  const signals=[record.signal_quality,...(record.signal_tags||[])].filter(Boolean).map(value=>SIGNAL_LABELS[value]||value);
  const classification=[record.content_type&&(CONTENT_LABELS[record.content_type]||record.content_type),record.review_status&&(REVIEW_LABELS[record.review_status]||record.review_status),record.state&&(STATE_LABELS[record.state]||record.state)].filter(Boolean);
  return `<article class="card">${mediaBlock(record,manifest)}<div class="card-body"><p class="account">${escapeHtml(record.account_display||record.account||'')} · ${escapeHtml(record.country||'地区未知')}</p><h2>${escapeHtml(title)}</h2><div>${badges(record.categories)}${badges(record.products)}${badges(record.feature_tags,'feature')}${badges(signals,'signal')}</div>${classification.length?`<p class="muted">${escapeHtml(classification.join(' · '))}</p>`:''}${!video&&!images.length&&record.media_reason?`<p class="media-note"><strong>${record.content_kind==='carousel'?'本机图集待恢复':'本机视频待恢复'}：</strong>${escapeHtml(record.media_reason)}</p>`:''}<div class="stats"><span>播放 <strong>${metric(record.metrics?.views)}</strong></span><span>点赞 <strong>${metric(record.metrics?.likes)}</strong></span><span>评论 <strong>${metric(record.metrics?.comments)}</strong></span><span>分享 <strong>${metric(record.metrics?.shares)}</strong></span></div>${record.view_delta!==undefined?`<p class="growth">播放增量 <strong>${metric(record.view_delta)}</strong> · 本期播放 ${metric(record.current_views)}</p>`:''}<p class="muted">发布 ${escapeHtml(record.published_at?.slice(0,10)||'日期未知')}${record.checked_at?` · 检查 ${escapeHtml(record.checked_at.slice(0,16))}`:''}</p>${sourceActions(record,{videos,images,cover})}</div></article>`;
}
function card(record,manifest,route){if(record.kind==='daily_summary')return summaryCard(record);if(route==='#/accounts')return accountCard(record);return contentCard(record,manifest);}
export function renderClosed(){return '<main class="closed"><div><span class="brand-mark">R</span><h1>网站暂时关闭</h1><p>请联系网站负责人确认恢复时间。</p></div></main>';}
export function renderRouteState({route='#/materials',error=false}={}){return `<header class="topbar"><a class="brand" href="#/materials"><span class="brand-mark">R</span><span><strong>素材雷达</strong><small>员工只读站</small></span></a><nav aria-label="主要页面">${nav(route)}</nav></header><main class="page"><section class="page-heading"><div><h1>${escapeHtml(ROUTE_LABELS.get(route)||'素材库')}</h1><p role="status" aria-live="polite">${error?'当前页面数据未能加载，请检查网络后重试。':'正在加载当前页面数据…'}</p>${error?'<button id="retry-route" type="button" class="primary">重新加载此页</button>':''}</div></section></main>`;}
const SUBMISSION_LABELS={pending:'待审核',approved:'已通过',rejected:'未采纳',duplicate:'重复账号'};
const TABLE_STATUS_LABELS={ready:'可提交',duplicate:'重复账号',invalid:'格式有误',conflict:'信息冲突',sending:'正在提交',submitted:'提交成功',failed:'提交失败',rate_limited:'额度不足'};
const TABLE_COLUMNS=['账号','昵称','国家/地区','类目','标签'];
function tablePreview(batch){
  if(!batch)return '<div class="import-empty"><p>选择原格式的 Excel 或 CSV 文件，先查看预检结果。</p><p class="muted">文件在当前浏览器内解析，确认提交前不会发送账号内容。</p></div>';
  const rows=batch.rows.map(row=>{
    const status=row.submission_state||row.status;
    const values=[row.account?`@${row.account}`:'',row.display_name,row.country,(row.categories||[]).join('、'),(row.tags||[]).join('、')];
    return `<tr><td class="source-rows">${escapeHtml((row.row_numbers||[]).join('、'))}</td>${values.map(value=>`<td>${escapeHtml(value||'—')}</td>`).join('')}<td class="import-state"><strong class="import-state-label state-${escapeHtml(status)}">${escapeHtml(TABLE_STATUS_LABELS[status]||status)}</strong><span>${escapeHtml(row.submission_message||row.message||'')}</span></td></tr>`;
  }).join('');
  const submitted=batch.rows.filter(row=>row.submission_state==='submitted').length;
  return `<section aria-labelledby="table-preview-heading"><h2 id="table-preview-heading">表格预检</h2><p class="muted import-filename">${escapeHtml(batch.filename)}${batch.sheet?` · ${escapeHtml(batch.sheet)}`:''}</p><p class="import-summary">源数据 ${escapeHtml(batch.total_rows)} 行 · 可提交 ${escapeHtml(batch.valid_count)} 个 · 重复 ${escapeHtml(batch.duplicate_count)} 个 · 需修正 ${escapeHtml(batch.invalid_count)} 个${submitted?` · 已提交 ${submitted} 个`:''}</p><div class="table-scroll" tabindex="0" role="region" aria-label="账号预检表格，可横向滚动"><table class="account-import-table"><thead><tr><th scope="col">源行</th>${TABLE_COLUMNS.map(label=>`<th scope="col">${label}</th>`).join('')}<th scope="col">预检与提交状态</th></tr></thead><tbody>${rows||'<tr><td colspan="7">没有可处理的账号。</td></tr>'}</tbody></table></div></section>`;
}
export function renderSubmissionPage({receipts=[],message='',error='',batch=null,parsing=false,enabled=false,refreshing=false}={}){
  const receiptsHtml=receipts.map(item=>`<li><strong>@${escapeHtml(item.username||'待识别')}</strong><span>${escapeHtml(SUBMISSION_LABELS[item.status]||item.status||'查询中')}</span>${item.review_note?`<small>${escapeHtml(item.review_note)}</small>`:''}</li>`).join('');
  const pending=(batch?.rows||[]).filter(row=>row.status==='ready'&&!['submitted','duplicate'].includes(row.submission_state)).length;
  const busy=parsing||Boolean(batch?.submitting);
  const canSubmit=enabled&&!busy&&pending>0;
  const hasAttempt=(batch?.rows||[]).some(row=>row.submission_state);
  const templateUrl=`data:text/csv;charset=utf-8,${encodeURIComponent('\ufeff'+TABLE_COLUMNS.join(',')+'\r\n')}`;
  return `<header class="topbar"><a class="brand" href="#/materials"><span class="brand-mark">R</span><span><strong>素材雷达</strong><small>员工只读站</small></span></a><nav aria-label="主要页面">${nav('#/submit')}</nav></header><main class="page submit-page"><section class="notice"><strong>无需登录，按表格提交</strong><p>沿用原来的五列格式；提交只进入管理员审核队列，不会立即启动监控或采集。</p></section><section class="page-heading"><div><p class="eyebrow">ACCOUNT DISCOVERY</p><h1>导入对标账号</h1><p class="muted">账号、昵称、国家/地区、类目、标签。已有账号只提示重复，不会覆盖原来的信息。</p></div><a class="template-download" href="${templateUrl}" download="对标账号导入模板.csv">下载五列表格模板</a></section><section class="submission-form import-form" aria-label="选择账号表格"><label for="account-table-file">选择 Excel / CSV 文件<input id="account-table-file" name="account_table" type="file" accept=".xlsx,.csv"${busy?' disabled':''} aria-describedby="import-help"></label><p id="import-help" class="muted">支持 .xlsx 和 UTF-8 CSV；单个工作表、最多 500 行数据、5 MB。第一行为五列表头；同一账号的多行会合并预检，冲突信息需先修正。</p></section>${!enabled?'<p class="submission-unavailable" role="status">账号提交暂时关闭；仍可在本机预检表格。</p>':''}<p id="submission-status" class="submission-status" role="status" aria-live="polite">${error?`<span class="error">${escapeHtml(error)}</span>`:escapeHtml(message)}</p>${tablePreview(batch)}<div class="import-submit-bar"><button id="table-submit" type="button" class="primary"${canSubmit?'':' disabled'}>${batch?.submitting?'正在提交…':parsing?'正在预检…':hasAttempt?`重试剩余 ${pending} 个账号`:`确认提交 ${pending} 个账号`}</button><p class="muted">额度按账号计算，不按文件计算：每浏览器每天 10 个、同一网络 30 个、全站 100 个。达到额度后会暂停，未提交行保留在当前页面。</p></div><section class="submission-history"><div class="submission-history-heading"><h2>本浏览器最近提交</h2><button id="refresh-submission-receipts" type="button"${refreshing||batch?.submitting||!receipts.length?' disabled':''}>${refreshing?'正在查询…':'刷新审核结果'}</button></div>${receiptsHtml?`<ul>${receiptsHtml}</ul>`:'<p class="muted">暂无提交记录。</p>'}<p class="muted">回执仅保存在当前浏览器；清除浏览器数据后无法恢复查询。刷新或关闭页面会清除尚未提交的表格预览。</p></section></main>`;
}
export function renderPage({route,manifest,allRecords,records,totalRecords=records.length,pagination={page:1,totalPages:1},filters={},summaryRecord=null,closed=false}){if(closed)return renderClosed();const title=ROUTE_LABELS.get(route)||'素材库',pool=filters.pool||'company',source=allRecords||records;const counts=poolCounts(source);const growthNotice=route==='#/brief'&&source.length&&!source.some(item=>Number.isFinite(item.view_delta))?'<p class="muted">本期尚无可比较的播放增量；可按最近记录的播放量查看，记录值不代表本期新采样。</p>':'';return `<header class="topbar"><a class="brand" href="#/materials"><span class="brand-mark">R</span><span><strong>素材雷达</strong><small>员工只读站</small></span></a><nav aria-label="主要页面">${nav(route)}</nav></header><main class="page"><section class="notice"><strong>公开只读 · 员工版本</strong><p>已与本机工作台同步，可筛选、播放、下载和查看原作品；管理与审核操作仍由本机管理员完成。</p></section><section class="page-heading"><div><p class="eyebrow">CONTENT INTELLIGENCE</p><h1>${title}</h1><p class="muted">版本 ${escapeHtml(manifest.version)} · ${escapeHtml(manifest.generated_at)}</p></div><div class="pool-tabs"><button data-pool="company" aria-pressed="${pool==='company'}">公司对标 ${counts.company}</button><button data-pool="market" aria-pressed="${pool==='market'}">市场对标 ${counts.market}</button><button data-pool="all" aria-pressed="${pool==='all'}">全部 ${counts.all}</button></div></section>${route==='#/today'?'<p class="muted"><strong>最近 7 天新作品：</strong>低于 10 万播放也会显示；正式素材仍按严格大于 10 万的入库规则处理。日期未知、未来日期和更早作品保留在观察记录。</p>':''}${filterForm(route,source,filters)}${growthNotice}<p id="result-status" class="result-status">筛选结果 ${totalRecords} 条 · 已同步总数 ${counts.all} 条 · 第 ${pagination.page}/${pagination.totalPages} 页</p>${summaryRecord?summaryCard(summaryRecord):''}<section id="records" class="record-grid">${records.length?records.map(item=>card(item,manifest,route)).join(''):'<div class="empty">当前条件没有记录。</div>'}</section>${paginationControls(pagination)}</main><dialog id="media-dialog"><div class="dialog-head"><strong id="media-label">媒体预览</strong><button type="button" data-dialog-close aria-label="关闭预览">关闭</button></div><p id="media-status" class="media-status" role="status">准备播放</p><video controls playsinline preload="metadata"></video><div class="dialog-actions"><a class="open-media" target="_blank" rel="noopener noreferrer">在新窗口打开</a><a class="download" target="_blank" rel="noopener noreferrer">下载文件</a></div></dialog><dialog id="gallery-dialog" aria-label="图集预览"><div class="dialog-head"><strong id="gallery-label">图集预览</strong><button id="gallery-close" type="button" aria-label="关闭图集预览">关闭</button></div><p id="gallery-status" class="media-status" role="status" aria-live="polite"></p><img id="gallery-image" class="gallery-image" alt="图集图片"><nav class="gallery-controls" aria-label="图集翻页"><button id="gallery-previous" type="button">上一张</button><span id="gallery-position" aria-live="polite"></span><button id="gallery-next" type="button">下一张</button></nav><div class="dialog-actions"><a id="gallery-open" target="_blank" rel="noopener noreferrer">在新窗口打开</a><a id="gallery-download" class="download" target="_blank" rel="noopener noreferrer">下载当前图片</a></div></dialog>`;}


